// mtp-eth-net suites — see main.cpp for the suite overview.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>

#include "eth_app.hpp"
#include "genet.hpp"
#include "net.hpp"
#include "platform.hpp"

#include <cstdint>
#include <cstdio>

#ifndef ETH_TEST_STATIC_IP
#define ETH_TEST_STATIC_IP ""
#endif
#ifndef ETH_TEST_GATEWAY
#define ETH_TEST_GATEWAY ""
#endif
#ifndef ETH_TEST_PEER
#define ETH_TEST_PEER ""
#endif

using namespace os::rtos;
namespace app = rpi4b::eth_app;
namespace net = rpi4b::net;
namespace genet = rpi4b::genet;
namespace platform = rpi4b::platform;

namespace
{
  app::bring_up_result g_up{};

  const char*
  fmt (const char* format, unsigned a, unsigned b = 0)
  {
    static char text[128];
    std::snprintf (text, sizeof (text), format, a, b);
    return text;
  }

  const char*
  fmt_str (const char* format, const char* s)
  {
    static char text[128];
    std::snprintf (text, sizeof (text), format, s != nullptr ? s : "");
    return text;
  }

  const char*
  fmt_ip (const char* label, std::uint32_t ip)
  {
    static char text[128];
    std::snprintf (text, sizeof (text), "%s: %u.%u.%u.%u", label,
                   static_cast<unsigned> ((ip >> 24) & 0xffu),
                   static_cast<unsigned> ((ip >> 16) & 0xffu),
                   static_cast<unsigned> ((ip >> 8) & 0xffu),
                   static_cast<unsigned> (ip & 0xffu));
    return text;
  }
} // namespace

// ===========================================================================
// 01 - Controller & PHY
// ===========================================================================
void
suite_controller (mt::suite& ts)
{
  ts.test ("GENET v5 MAC and BCM54213PE RGMII PHY respond", [] (auto& t) {
    g_up = app::bring_up (ETH_TEST_STATIC_IP, ETH_TEST_GATEWAY);
    const unsigned ver = genet::version ();
    const std::uint32_t phy = genet::phy_id ();
    std::printf ("# GENET v%u, PHY ID 0x%08x\n", ver,
                 static_cast<unsigned> (phy));
    t.expect (g_up.controller) << "genet::start () succeeded";
    t.expect (mt::eq (ver, 5u))
        << "Broadcom GENET major version 5 (SYS_REV_CTRL)";
    t.expect (mt::all_of (mt::ne (phy, 0u), mt::ne (phy, 0xffffffffu)))
        << fmt ("BCM54213PE MDIO PHY ID 0x%08x", static_cast<unsigned> (phy));
  });

  ts.test ("station MAC address is a valid unicast address", [] (auto& t) {
    const auto& mac = genet::address ();
    const char* src = genet::address_source ();
    std::printf ("# MAC %02x:%02x:%02x:%02x:%02x:%02x (%s)\n", mac[0], mac[1],
                 mac[2], mac[3], mac[4], mac[5], src);
    const bool non_zero
        = (mac[0] | mac[1] | mac[2] | mac[3] | mac[4] | mac[5]) != 0;
    const bool unicast = (mac[0] & 0x01u) == 0;
    t.expect (non_zero) << "station MAC address is non-zero";
    t.expect (unicast) << "MAC I/G bit is 0 (unicast)";
    t.expect (src != nullptr && src[0] != '\0')
        << fmt_str ("MAC address source: %s", src);
  });
}

// ===========================================================================
// 02 - Link & DHCP
// ===========================================================================
void
suite_link_dhcp (mt::suite& ts)
{
  ts.test ("RGMII physical link auto-negotiated", [] (auto& t) {
    const unsigned spd = genet::speed ();
    const bool fdx = genet::full_duplex ();
    std::printf ("# link: %s, %u Mbit/s %s duplex\n",
                 g_up.link ? "up" : "down", spd, fdx ? "full" : "half");
    t.expect (g_up.link && net::link_up () && genet::linked ())
        << "RGMII link is up";
    t.expect (spd == 10u || spd == 100u || spd == 1000u)
        << fmt ("negotiated speed %u Mbit/s", spd);
  });

  ts.test ("lwIP netif configured with IPv4 address and gateway", [] (auto& t) {
    const std::uint32_t ip = net::address ();
    const std::uint32_t gw = net::gateway ();
    std::printf ("# IPv4 %u.%u.%u.%u (%s), gateway %u.%u.%u.%u\n",
                 static_cast<unsigned> ((ip >> 24) & 0xffu),
                 static_cast<unsigned> ((ip >> 16) & 0xffu),
                 static_cast<unsigned> ((ip >> 8) & 0xffu),
                 static_cast<unsigned> (ip & 0xffu),
                 g_up.leased ? "DHCP" : "static",
                 static_cast<unsigned> ((gw >> 24) & 0xffu),
                 static_cast<unsigned> ((gw >> 16) & 0xffu),
                 static_cast<unsigned> ((gw >> 8) & 0xffu),
                 static_cast<unsigned> (gw & 0xffu));
    t.expect (g_up.address && net::has_address ())
        << (g_up.leased ? "IPv4 lease acquired via DHCP"
                        : "static IPv4 address configured");
    t.expect (mt::ne (ip, 0u)) << fmt_ip ("interface IPv4", ip);
    t.expect (mt::ne (gw, 0u)) << fmt_ip ("gateway IPv4", gw);
    t.expect (mt::ne (ip, gw))
        << "interface IPv4 is distinct from gateway IPv4";
  });
}

// ===========================================================================
// 03 - ICMP & Counters
// ===========================================================================
void
suite_icmp_counters (mt::suite& ts)
{
  ts.test ("gateway answers 56-byte ICMP echo requests", [] (auto& t) {
    unsigned replies = 0;
    if (g_up.address)
      {
        app::serve_for (50);
        const char* gateway
            = ETH_TEST_GATEWAY[0] != '\0' ? ETH_TEST_GATEWAY : "gw";
        replies = net::ping (gateway, 4, 56);
        app::log ("ping gateway (56 B): %u of 4 replies\n", replies);
      }
    std::printf ("# ICMP echo (56 B payload): %u / 4 replies\n", replies);
    t.expect (mt::gt (replies, 0u))
        << fmt ("%u of 4 ICMP echo replies (56 B)", replies);
  });

  ts.test ("gateway answers 256-byte ICMP echo requests", [] (auto& t) {
    unsigned replies = 0;
    if (g_up.address)
      {
        const char* gateway
            = ETH_TEST_GATEWAY[0] != '\0' ? ETH_TEST_GATEWAY : "gw";
        replies = net::ping (gateway, 2, 256);
        app::log ("ping gateway (256 B): %u of 2 replies\n", replies);
        if (ETH_TEST_PEER[0] != '\0')
          {
            const unsigned peer = net::ping (ETH_TEST_PEER, 2, 56);
            app::log ("ping %s: %u of 2 replies\n", ETH_TEST_PEER, peer);
          }
      }
    std::printf ("# ICMP echo (256 B payload): %u / 2 replies\n", replies);
    t.expect (mt::gt (replies, 0u))
        << fmt ("%u of 2 ICMP echo replies (256 B)", replies);
  });

  ts.test ("GENET v5 DMA TX and RX rings report error-free frame traffic",
           [] (auto& t) {
             const auto& st = genet::stats ();
             app::log ("frames: rx %u (%u errors), tx %u (%u errors)\n",
                       static_cast<unsigned> (st.rx_frames),
                       static_cast<unsigned> (st.rx_errors),
                       static_cast<unsigned> (st.tx_frames),
                       static_cast<unsigned> (st.tx_errors));
             std::printf (
                 "# frames: rx %u (%u errors), tx %u (%u errors), %u link "
                 "change(s)\n",
                 static_cast<unsigned> (st.rx_frames),
                 static_cast<unsigned> (st.rx_errors),
                 static_cast<unsigned> (st.tx_frames),
                 static_cast<unsigned> (st.tx_errors),
                 static_cast<unsigned> (st.link_changes));
             t.expect (mt::ge (st.tx_frames, 6u))
                 << fmt ("TX DMA ring sent %u frames", st.tx_frames);
             t.expect (mt::ge (st.rx_frames, 6u))
                 << fmt ("RX DMA ring received %u frames", st.rx_frames);
             t.expect (mt::eq (st.tx_errors, 0u)) << "0 TX DMA errors";
             t.expect (mt::eq (st.rx_errors, 0u)) << "0 RX DMA errors";
           });
}

// ===========================================================================
// 04 - SD Card Log
// ===========================================================================
void
suite_sd_log (mt::suite& ts)
{
  ts.test ("SD card FAT32 volume mounted by background thread", [] (auto& t) {
    const std::uint32_t start = platform::millis ();
    while (!app::saver_ready () && platform::millis () - start < 10000u)
      {
        net::poll ();
        sysclock.sleep_for (2);
      }
    t.expect (app::saver_ready ()) << "SD saver thread completed card init";
    t.expect (!app::saver_failed ())
        << "FAT32 volume mounted and tests/ directory ready";
  });

  ts.test ("network run log saved to tests/MTPNET.LOG and verified by read-back",
           [] (auto& t) {
             app::log ("verdict: PASS\n");
             const std::uint32_t sz = app::log_size ();
             const bool saved
                 = app::save_and_wait ("MTPNET.LOG", app::log_text (), sz);
             std::printf ("# SD log: tests/MTPNET.LOG, %u bytes, saved=%s\n",
                          static_cast<unsigned> (sz), saved ? "yes" : "no");
             t.expect (mt::gt (sz, 0u))
                 << fmt ("log buffer holds %u bytes", sz);
             t.expect (saved)
                 << "written to tests/MTPNET.LOG and verified byte-for-byte";
           });
}
